        var qty = e.read ? window.LK_AMT.say(e.n, e.u) : '', i = S.fnNeed.push({ text: e.name, qty: qty, recipe: e.link, k: e.k, day: d.day, fids: Object.keys(e.fids || {}).slice(0, 4) }) - 1;
