    if (a === 'dk-save') { dkSave(); return; }
    if (a === 'dk-edit') { dkEdit(); draw(); focusSel('.dr-form'); return; }
    if (a === 'dk-cancel') { if (dkDirty() && !arm('dk-cancel')) return; dkEditing = false; dkf = null; dkSnap = ''; dkMsg = ''; draw(); return; }
