    backDescription: function () { return S.root && document.body.contains(S.root) && S.root.querySelector('#prep-leave-note') ? 'prep-leave-note' : ''; },
    mount: function (name, root, sel) {
      wire();
      S.name = name; S.root = root;
      try { finFresh(); } catch (e) {}
      if (name === 'guides') { if ((sel || '') !== S.gSel) S.gSel = sel || ''; }
      if (name === 'admin') S.draft = S.draft || null;
      draw();
      if (name === 'todo' || chefPage('todo')) todoLoad(TD_FRESH);
      if (name === 'team' || chefPage('plan')) teamLoad(TM_FRESH);
      if (S.pin) { connect(); if (name === 'admin') sdk(); if (name === 'orders') { S.ordDate = dayNow(); watchOrders(); } if (name === 'waste') { S.wDate = dayNow(); watchWaste(); } if (name === 'transfers') { S.xDate = dayNow(); watchXfer(); } notesInit(); }
    },
    warm: function () { sdk().then(function () { rxSync(); }).catch(function () {}); if (S.pin && S.configState !== 'ok' && S.configState !== 'loading') connect(); notesInit(); },
    unsaved: function () { return sendingNow() || unsavedHere(); },
    // a write waiting for the server (part of unsaved()), so Update now can say "Not sent yet." like the strip
    unsent: sendingNow,
    // the rest of unsaved(): typed or open here, so the chef hat's Sign out says "Not saved yet." or "Not sent yet."
    unsavedHere: unsavedHere,
    noteInfo: noteInfo, noteBellLabel: noteBellLabel,
    noteOpen: noteOpen,
    // the recipes were opened: look for the head chef's recipe changes when the last look is 30 minutes old
    rxCheck: function () { sdk().then(function () { rxSync(); }).catch(function () {}); },
    rxSync: rxSync,
    rxState: function () { return rxState; },
    guidesFor: function (rid) { try { return guidesFor(rid); } catch (e) { return []; } },
    guideSearch: function (q) { try { return guideSearch(q); } catch (e) { return []; } },
    featOn: featOn,
    ownerHere: ownerHere,
    whoName: whoName,
    homeGreet: homeGreet,
    // The signed-in person's staff id, only while their name shows (the kitchen mascot keeps one shuffled set per person).
    whoId: function () { return whoName() ? S.who : ''; },
    // the no-signal sentence while the kitchen's settings are not loaded and there is no signal, otherwise '' (js/app.js)
    offline: function () { return offWait() ? OFF_KITCHEN : ''; },
    // Sign in from the chef hat with nobody signed in: "Who are you?" on the prep list, then back to the page it came from.
    // Not with no signal before the settings are in: the person on this phone is known, and this would forget them
    signIn: function (back) {
      if (whoName() || offWait()) return;
      if (blockedRecorder()) { S.pending = back && back !== '#/prep' && back.indexOf('#/') === 0 ? { back: back } : null; pickName(blockedRecorder()); if (location.hash !== '#/prep') location.hash = '#/prep'; return; }
      S.picking = true; S.who = ''; S.pending = back && back !== '#/prep' && back.indexOf('#/') === 0 ? { back: back } : null;
      if (location.hash === '#/prep') draw(); else location.hash = '#/prep';
      window.scrollTo(0, 0);
    },
    headPin: whoHead,
    bookEdit: bookEdit,
    bookState: bookState,
    fnOK: fnOK, fnCancelOK: fnCancelOK, toast: toast, btnPatch: btnPatch,
    fnState: fnState,
    // Who has seen a function (10 Nov 2026, js/functions.js seenHTML()): the head chef, the sous chefs and the admin ask;
    // the kitchen people who could have (active, on the staff list, not functions only), by id and name
    fnSeenOK: chefAllowed,
    fnPeople: function () { return ptPeople().map(function (p) { return { id: p.id, name: p.name }; }); },
    todoOK: todoOK, cleaningOK: cleaningOK, cleaning: cleaningApi,
    // Today's team (7 Nov 2026): the chef chip in the top bar and its icon for the chef hat tile (js/app.js)
    teamOK: teamOK, teamChip: teamChipHTML, teamIcon: tmIcon,
    book: bookApi,
    supplier: supplierApi,
    chefMenu: chefMenu,
    chefOpen: chefOpen,
    // Settings (3 Nov 2026, docs/settings-options/brief.md): the person's role and permissions, the kitchen's settings
    // for the verified admin, and the cut-off pushes on this phone (the same pushOn() and pushOff() as the order list)
    whoRole: whoRole, myCan: myCan, kitchenInfo: kitchenInfo, adminOpen: adminOpen, forgetPin: forgetPin,
    push: function () { var w = pushWhoId(), st = w ? pushState() : ''; return { show: !!w, on: st === 'on', busy: !!S.pushBusy, msg: S.pushMsg || (st === 'ios' || st === 'denied' ? PUSH_SAY[st] : '') }; },
    pushSet: function (on) { if (on) pushOn(); else pushOff(); },
    coolingChip: function () { var c = coolingGet(); return c ? c.chipHTML() : ''; },
    coolingOpen: coolingOpen, coolingRoute: coolingRoute, coolingPaint: coolingPaint,
    secOpen: function () { ksOpen(true); },
    // Manual Sign out never overrides unsent work. Automatic locks retain it behind the original person's PIN.
    signOut: function (force, quiet) { if (sendFirst()) { toast(SEND_FIRST); return false; } return signOutPerson(force, quiet); },
    sendFirst: sendFirst,
    minNudge: minNudgeHTML,
