    homeOn: homeOn, homeSlot: homeSlot, homePaint: homePaint, homeCutSlot: homeCutSlot,
    cutSlot: cutSlot, cutHat: cutHat,
    mailInfo: mlInfo,
    mailTab: mailTab,
